import json
old = json.load(open('migrations/20260810222911_lethal_virginia_dare/snapshot.json'))
new = json.load(open('.dkg-test/migrations/20260818135330_public_miracleman/snapshot.json'))

def norm_entities(snap):
    cols, idx, fks, pks, uniques, checks, tables = [], [], [], [], [], [], []
    for x in snap['ddl']:
        e = x.get('entityType')
        if e=='columns':
            c = dict(x)
            d = c.get('default')
            if d in ('0','1','false','true'):
                c['default'] = {'0':'false','1':'true','false':'false','true':'true'}[str(d)]
            cols.append(c)
        elif e=='indexes': idx.append(x)
        elif e=='fks': fks.append(x)
        elif e=='pks': pks.append(x)
        elif e=='uniques': uniques.append(x)
        elif e=='checks': checks.append(x)
        elif e=='tables': tables.append(x['name'])
    return tables, cols, idx, fks, pks, uniques, checks

ot, oc, oi, of, op, ou, oc2 = norm_entities(old)
nt, nc, ni, nf, np, nu, nc3 = norm_entities(new)

def diff(a, b, label):
    sa = {json.dumps(x, sort_keys=True) for x in a}
    sb = {json.dumps(x, sort_keys=True) for x in b}
    only_old = sa - sb
    only_new = sb - sa
    print(f'{label}: only_old={len(only_old)} only_new={len(only_new)}')
    for x in list(only_old)[:5]:
        print('  OLD ONLY:', x[:180])
    for x in list(only_new)[:5]:
        print('  NEW ONLY:', x[:180])

print('tables same:', set(ot)==set(nt), len(ot), len(nt))
diff(oc, nc, 'columns')
diff(oi, ni, 'indexes')
diff(of, nf, 'fks')
diff(op, np, 'pks')
diff(ou, nu, 'uniques')
"

